#include "test_common.h"
#include "linked_list.h"
static bool pred(const void *d,const void *k){return *(const int*)d==*(const int*)k;} static int32_t cmp(const void*a,const void*b){return (*(const int*)a>*(const int*)b)-(*(const int*)a<*(const int*)b);} static BmsStatus_t countv(void*d,void*c){(void)d;(*(uint32_t*)c)++;return BMS_STATUS_OK;}
static void test_lifecycle(void){BmsLinkedList_t l;int a=3,b=1,c=2,key=1,repl=9;void *found=NULL;uint32_t n=0;ASSERT_OK(LinkedListInitialize(&l,sizeof(int)));CU_ASSERT_TRUE(LinkedListIsEmpty(&l));ASSERT_OK(LinkedListInsertBack(&l,&a));ASSERT_OK(LinkedListInsertFront(&l,&b));ASSERT_OK(LinkedListInsertBack(&l,&c));CU_ASSERT_EQUAL(LinkedListGetCount(&l),3U);ASSERT_OK(LinkedListFind(&l,pred,&key,&found));CU_ASSERT_EQUAL(*(int*)found,1);ASSERT_OK(LinkedListUpdate(&l,pred,&key,&repl));ASSERT_OK(LinkedListSort(&l,cmp));ASSERT_OK(LinkedListTraverse(&l,countv,&n));CU_ASSERT_EQUAL(n,3U);key=2;ASSERT_OK(LinkedListDelete(&l,pred,&key));CU_ASSERT_EQUAL(LinkedListGetCount(&l),2U);LinkedListClear(&l);CU_ASSERT_TRUE(LinkedListIsEmpty(&l));}
void RegisterLinkedListTests(void){CU_pSuite s=CU_add_suite("Linked List",NULL,NULL);CU_add_test(s,"CRUD sort traverse",test_lifecycle);}
